mapper.select:
SELECT d.id, d.type, d.title, d.content, d.kb_id AS kbId, kb.name AS kbName, d.creator_id AS creatorId, u.name AS creatorName, d.updated_at AS updatedAt, d.view_count AS viewCount, NULL AS coverUrl FROM document d LEFT JOIN knowledge_base kb ON d.kb_id = kb.id LEFT JOIN user u ON d.creator_id = u.id
AND (d.title LIKE CONCAT('%', #{keyword}, '%') OR d.content LIKE CONCAT('%', #{keyword}, '%'))
AND d.type = #{type}
AND d.kb_id = #{kbId}
AND d.creator_id = #{creatorId}
AND d.updated_at >= #{startTime}
AND d.updated_at <= #{endTime}
ORDER BY d.updated_at DESC

SELECT kb.id, 'KNOWLEDGE_BASE' AS type, kb.name AS title, kb.description AS content, NULL AS kbId, NULL AS kbName, kb.creator_id AS creatorId, u.name AS creatorName, kb.updated_at AS updatedAt, 0 AS viewCount, kb.cover_url AS coverUrl FROM knowledge_base kb LEFT JOIN user u ON kb.creator_id = u.id
AND (kb.name LIKE CONCAT('%', #{keyword}, '%') OR kb.description LIKE CONCAT('%', #{keyword}, '%'))
AND kb.creator_id = #{creatorId}
AND kb.updated_at >= #{startTime}
AND kb.updated_at <= #{endTime}
ORDER BY kb.updated_at DESC
